      "printed_page": "458",
      "headings": [
        {"level": "running_header", "text": "HEIDEGGER EN FRANCE", "position": "top"}
      ],
      "paragraph_starts": [
        {"text": "prétative dont il tient le modèle exemplaire de Heidegger lui-même (radicalisation", "continues_from_previous": true, "continues_to_next": false},
        {"text": "À l'examen, Lévinas est beaucoup plus proche de Heidegger qu'il ne", "continues_from_previous": false, "continues_to_next": false},
        {"text": "Il faut d'abord reprendre l'étude de la question éthique chez Heidegger", "continues_from_previous": false, "continues_to_next": true}
      ],
      "body_note_refs": [
        {"marker": "48", "context": "etc.^48"},
