        {"marker": "49", "text_start": "Ibid., p. 157."},
        {"marker": "50", "text_start": "Formulation que nous empruntons à ZARADER, ibid., p. 158."},
        {"marker": "51", "text_start": "Voir HEIDEGGER, Lettre sur l'humanisme, op. cit., p. 134-135"},
        {"marker": "52", "text_start": "Voir ibid., pp. 144-145"}
