      "paragraph_starts": [
        {"text": "nologie est d'emblée déchirée (ou biaisée ?) par la transcendance à l'égard", "continues_from_previous": true, "continues_to_next": false},
        {"text": "Bien qu'il ne faille nullement dispenser la pensée heideggérienne d'un examen", "continues_from_previous": false, "continues_to_next": false}
      ],
